#include "support/store_write_peer.h"
static void swWork(xmqttversion Version)
{
    jpdrive D={0};jpfile F=jpFile(&D);xmqttjournalconfig JC=stJournalConfig(Version);xmqttjournal* J=jpCreate(F,&JC);xmqttstorestateconfig SC=stConfig(Version);SC.WallMilliseconds=0;xmqttstorestate* State=NULL;stStatus(xmqttStoreStateRecover(J,&SC,&State),XMQTT_STORE_DONE,"work-bound source");xtaskpool* Pool=jwPool(1);xmqttstorewriteconfig C;xmqttStoreWriteConfigInit(&C);C.MaxModelWork=6;xmqttstorewrite* W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,State,&C,&W),"explicit model work cap");sdsource Source;sdSource(Version,&Source);xfuture* Future=swOps(W,&SC.Delta,Source.Ops,2);testRequire(jwOutcome(Future)->Status==XMQTT_COMMIT_OK,"actual BIND/OPEN");xrtFutureDestroy(Future);
    xmqttstoredelta Puts[2]={Source.Ops[2],Source.Ops[4]};Future=swOps(W,&SC.Delta,Puts,2);testRequire(jwOutcome(Future)->Status==XMQTT_COMMIT_OK,"two original owned payloads");xrtFutureDestroy(Future);xmqttstorewriteinfo Before=swInfo(W);unsigned Calls=D.Calls;
    xmqttstoredelta Reset[3]={{.Type=XMQTT_STORE_END,.Epoch=1,.WallMilliseconds=1002,.Expiry=Version==XMQTT_VERSION_5?60:UINT32_MAX},{.Type=XMQTT_STORE_CLEAR,.Epoch=1,.WallMilliseconds=1003},{.Type=XMQTT_STORE_OPEN,.Epoch=2,.WallMilliseconds=1004,.Expiry=Version==XMQTT_VERSION_5?60:UINT32_MAX}};Future=swOps(W,&SC.Delta,Reset,3);const xmqttcommitresult* R=jwOutcome(Future);xmqttstorewriteinfo After=swInfo(W);
    testRequire(R->Status==XMQTT_COMMIT_LIMIT&&!R->AppendCalled&&D.Calls==Calls&&!After.Worker.Failed&&After.State.Transactions==Before.State.Transactions&&After.State.Operations==Before.State.Operations&&After.State.MemoryBytes==Before.State.MemoryBytes&&After.State.Outgoing==2&&After.State.Epoch==1,"nonzero work cap aborts reset after one virtual deletion without IO or model change");xrtFutureDestroy(Future);
    Future=swOps(W,&SC.Delta,Source.Ops+3,1);testRequire(jwOutcome(Future)->Status==XMQTT_COMMIT_OK&&swInfo(W).State.Outgoing==2&&swInfo(W).State.Transactions==3,"ordinary flow remains valid after partially staged END/reset refusal");xrtFutureDestroy(Future);testRequire(xmqttStoreWriteDestroy(W),"work-limited owner retirement");jwPoolDone(Pool);jpFileClose(F);
}
static void swQueued(void)
{
    jpdrive D={0};jpfile F=jpFile(&D);xmqttjournalconfig JC=stJournalConfig(XMQTT_VERSION_5);xmqttjournal* J=jpCreate(F,&JC);xmqttstorestateconfig SC=stConfig(XMQTT_VERSION_5);SC.WallMilliseconds=0;xmqttstorestate* State=NULL;stStatus(xmqttStoreStateRecover(J,&SC,&State),XMQTT_STORE_DONE,"queued source");xtaskpool* Pool=jwPool(1);jwblock Block={0};xfuture* Holding=xrtTaskSubmit(Pool,jwBlock,&Block,NULL);jwAwait(&Block.Started);xmqttstorewriteconfig C;xmqttStoreWriteConfigInit(&C);xmqttstorewrite* W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,State,&C,&W),"queued semantic owner");sdsource Source;sdSource(XMQTT_VERSION_5,&Source);xmqttstoredelta Bad=Source.Ops[0];Bad.Data=XRT_BYTES_LITERAL("other");xfuture* A=swOps(W,&SC.Delta,&Bad,1);xfuture* B=swOps(W,&SC.Delta,Source.Ops,2);xfuture* E=swOps(W,&SC.Delta,Source.Ops+2,1);xrtAtomic32Store(&Block.Released,1,XMEMORY_RELEASE);
    testRequire(jwOutcome(A)->Status==XMQTT_COMMIT_INVALID&&!jwOutcome(A)->AppendCalled&&jwOutcome(B)->Status==XMQTT_COMMIT_OK&&jwOutcome(B)->Sequence==1&&jwOutcome(E)->Status==XMQTT_COMMIT_OK&&jwOutcome(E)->Sequence==2,"queued siblings validate against preceding committed model,not admission-time snapshots");testRequire(swInfo(W).State.Outgoing==1&&swInfo(W).State.Transactions==2&&xmqttStoreWriteDestroy(W),"queued semantic commits physically retired");jwPoolDone(Pool);jpFileClose(F);xrtFutureDestroy(A);xrtFutureDestroy(B);xrtFutureDestroy(E);xrtFutureDestroy(Holding);
}
int main(void){swWork(XMQTT_VERSION_5);swWork(XMQTT_VERSION_311);swQueued();puts("[PASS] partial reset work-budget rollback on both versions and queued invalid/valid dependent FIFO transactions");return 0;}
